hooks.command:
$j=[Console]::In.ReadToEnd()
$m=[regex]::Matches($j,'from //Codex/main/[^"]*?([a-z]+)-workplan\.md')
if($m.Count -gt 0){
  $names=($m | ForEach-Object { $_.Groups[1].Value } | Sort-Object -Unique) -join ', '
  @{hookSpecificOutput=@{hookEventName='PostToolUse';additionalContext="MERGE-DOWN CHANGED WORKPLANS: $names. Read each one NOW, before continuing. Absorb any findings-outbox entry addressed to you or to the fleet, and delete from the author's outbox the ones you have absorbed. Do not defer this to the next init -- a workplan read once at init is remembered wrong, which is how a live entry gets missed."}} | ConvertTo-Json -Compress -Depth 5
}
